Lemma fz_B1 : forall (fr : bvmap 5 word) cs regs (m : word -> option byte) (s pix : Z),
  frm_zero cs ->
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  (1 <= pix < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  getr regs 10 = Z_to_bv 64 pix ->
  reach SEGS (@mkst (mkFP fr cs) regs (Z_to_bv 64 405492) m rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (Z_to_bv 64 635328) M' rom /\ frm_zero cs' /\
      rinv [((s - 48)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (s - 48)) 8 = Some (Z_to_le_bytes 8 pix) /\
      getr regs' 1 = Z_to_bv 64 405532 /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 10 = Z_to_bv 64 pix /\ getr regs' 11 = Z_to_bv 64 (s - 32) /\
      getr regs' 12 = Z_to_bv 64 (s - 36) /\ getr regs' 13 = Z_to_bv 64 (s - 28) /\ getr regs' 14 = Z_to_bv 64 0 /\
      regs_agree (fun r => In r [1; 11; 12; 13; 14]%list) regs regs' /\
      reg_get fr' 10 = Z_to_bv 64 18446744070479937536 /\ reg_get fr' 11 = Z_to_bv 64 18446744070479937536 /\
      (forall r : reg, ~ In (ridx r) [10; 11]%nat -> reg_get fr' r = reg_get fr r)).
