Lemma fz_D : forall (fx : FPState) regs (m : word -> option byte) (s : Z),
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 405544) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 445244) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 405552 /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 10 = Z_to_bv 64 (s - 56) /\
